import{_ as a,o as d,c as r,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"帮助页：随手查","description":"","frontmatter":{},"headers":[],"relativePath":"use/help-page.md","filePath":"use/help-page.md","lastUpdated":null}'),o={name:"use/help-page.md"};function s(h,t,l,n,i,c){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="帮助页-随手查" tabindex="-1">帮助页：随手查 <a class="header-anchor" href="#帮助页-随手查" aria-label="Permalink to &quot;帮助页：随手查&quot;">​</a></h1><p><strong>控制台第六页，也是默认打开的那一页。</strong> 不需要连电脑就能查说明。</p><h2 id="为什么默认停在这一页" tabindex="-1">为什么默认停在这一页 <a class="header-anchor" href="#为什么默认停在这一页" aria-label="Permalink to &quot;为什么默认停在这一页&quot;">​</a></h2><p>第一次打开控制台的人，最需要知道的是「这六个页面各干什么」。</p><p>所以框架把「帮助」设成默认页 —— 打开就是说明书。</p><h2 id="帮助页有什么" tabindex="-1">帮助页有什么 <a class="header-anchor" href="#帮助页有什么" aria-label="Permalink to &quot;帮助页有什么&quot;">​</a></h2><p>按页面顺序列出六页的用途和常用操作：</p><table tabindex="0"><thead><tr><th>页面</th><th>帮助里会写</th></tr></thead><tbody><tr><td><strong>参数</strong></td><td>怎么拖滑块、怎么导入分享码、改完要重开</td></tr><tr><td><strong>Mod</strong></td><td>怎么禁用/启用/删除、怎么分享、冲突怎么办</td></tr><tr><td><strong>存档</strong></td><td>怎么改威望和回合、要记得点保存</td></tr><tr><td><strong>日志</strong></td><td>三级日志是什么、怎么筛选、怎么导出</td></tr><tr><td><strong>状态</strong></td><td>偏离清单是什么、怎么用</td></tr><tr><td><strong>帮助</strong></td><td>就这一页</td></tr></tbody></table><h2 id="为什么把说明做进游戏内" tabindex="-1">为什么把说明做进游戏内 <a class="header-anchor" href="#为什么把说明做进游戏内" aria-label="Permalink to &quot;为什么把说明做进游戏内&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">一个很实际的理由</p><p>框架的文档（就是你正在看的这个网站）在电脑上，而玩家在<strong>手机上玩游戏</strong>。</p><p>如果玩家遇到问题要切到电脑查文档，这个体验是断的。</p><p>所以框架把<strong>最常用的说明</strong>做进了游戏内的帮助页 —— 手机上随时能看。</p></div><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>看帮助页的哪部分</th></tr></thead><tbody><tr><td>第一次用，不知道从哪开始</td><td>全部扫一遍（一分钟）</td></tr><tr><td>忘了分享码怎么导入</td><td>「参数」那一段</td></tr><tr><td>不确定删除按钮会不会删文件</td><td>「Mod」那一段</td></tr><tr><td>改了存档没生效</td><td>「存档」那一段</td></tr><tr><td>日志太多不知道看哪个</td><td>「日志」那一段</td></tr></tbody></table><h2 id="和本站的关系" tabindex="-1">和本站的关系 <a class="header-anchor" href="#和本站的关系" aria-label="Permalink to &quot;和本站的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>渠道</th><th>适合</th></tr></thead><tbody><tr><td><strong>游戏内帮助页</strong></td><td>快速查「怎么操作」，手机上随时看</td></tr><tr><td><strong>本站（文档站）</strong></td><td>深入了解「为什么这样」「完整规范」「进阶玩法」</td></tr></tbody></table><p>游戏内帮助页是<strong>精简版</strong>，本站是<strong>完整版</strong>。两者内容一致，只是详细程度不同。</p><h2 id="看完帮助页之后" tabindex="-1">看完帮助页之后 <a class="header-anchor" href="#看完帮助页之后" aria-label="Permalink to &quot;看完帮助页之后&quot;">​</a></h2><p>如果帮助页没解决你的问题：</p><ol><li><strong>去状态页</strong> —— 看当前是什么状况</li><li><strong>去日志页</strong> —— 看有没有报错</li><li><strong>查本站</strong> —— 用右上角的搜索，或者按下面的索引找</li></ol><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to &quot;文档索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想知道</th><th>去哪</th></tr></thead><tbody><tr><td>框架能做什么</td><td><a href="/AtlanticFleetSite/docs/what-is-afmod">这是什么</a></td></tr><tr><td>怎么装</td><td><a href="/AtlanticFleetSite/docs/deploy/">安装部署</a></td></tr><tr><td>怎么调数值</td><td><a href="/AtlanticFleetSite/docs/use/params-page">参数页</a></td></tr><tr><td>某个参数是什么</td><td><a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a></td></tr><tr><td>为什么点了发射没反应</td><td><a href="/AtlanticFleetSite/docs/use/status-page">状态页</a></td></tr><tr><td>怎么自己做 Mod</td><td><a href="/AtlanticFleetSite/docs/dev/mod-json">mod.json 完整规范</a></td></tr><tr><td>出问题了</td><td><a href="/AtlanticFleetSite/docs/use/troubleshooting">出问题了怎么查</a></td></tr><tr><td>常见问题</td><td><a href="/AtlanticFleetSite/docs/faq">常见问题</a></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>六个页面总览 → <a href="/AtlanticFleetSite/docs/use/panel">游戏内控制台「小u」</a></li><li>操作技巧 → <a href="/AtlanticFleetSite/docs/use/gestures">悬浮窗操作技巧</a></li><li>遇到问题 → <a href="/AtlanticFleetSite/docs/use/troubleshooting">出问题了怎么查</a></li></ul>',22)])])}const b=a(o,[["render",s]]);export{u as __pageData,b as default};
